'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() {
  let resolve, reject;
  const promise = new Promise((a, b) => { resolve = a; reject = b; });
  return { promise, resolve, reject };
}

async function main() {
  // Detached flight must not delete newer flight (dedup preserved) nor commit.
  {
    const gates = [deferred(), deferred()];
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b1 = c.get('k'); await tick();
    gates[0].resolve('old'); assert.equal(await a, 'old');
    const b2 = c.get('k');
    assert.equal(calls, 2, 'newer flight still shared');
    gates[1].resolve('new');
    assert.equal(await b1, 'new'); assert.equal(await b2, 'new');
    assert.equal(await c.get('k'), 'new'); assert.equal(c.size, 1);
  }
  // Rejection not cached; all waiters same reason; retry works; detached rejection keeps newer flight.
  {
    let calls = 0; const reason = { not: 'error' };
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw reason; return 'ok'; } });
    const [r1, r2] = await Promise.allSettled([c.get('k'), c.get('k')]);
    assert.equal(r1.reason, reason); assert.equal(r2.reason, reason);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 2);
  }
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].reject(new Error('x')); await assert.rejects(a);
    c.get('k'); assert.equal(calls, 2);
    gates[1].resolve('v'); assert.equal(await b, 'v');
  }
  // set wins; old load can't restart TTL; expiry starts new load not detached one.
  {
    let t = 0; const gates = [deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.set('k', 'manual');
    t = 5; gates[0].resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'manual');
    t = 10; assert.equal(c.size, 0);
    const b = c.get('k'); await tick(); assert.equal(calls, 2);
    gates[1].resolve('fresh'); assert.equal(await b, 'fresh');
  }
  // TTL from commit; ttl 0 never reuses but dedups.
  {
    let t = 0; const g = deferred(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => { calls++; return calls === 1 ? g.promise : 'n'; } });
    const a = c.get('k'); await tick(); t = 8; g.resolve('v'); await a;
    t = 17; assert.equal(await c.get('k'), 'v'); t = 18; assert.equal(await c.get('k'), 'n');
  }
  {
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++calls });
    const [x, y] = await Promise.all([c.get('k'), c.get('k')]);
    assert.equal(x, 1); assert.equal(y, 1); assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  // Load mutating synchronously, and joining its own flight.
  {
    let calls = 0; let c;
    c = createCache({ now: () => 0, load: k => { calls++; if (calls === 1) { c.invalidate(k); return 'stale'; } return 'fresh'; } });
    assert.equal(await c.get('k'), 'stale'); assert.equal(await c.get('k'), 'fresh');
  }
  {
    let c; let joined;
    c = createCache({ now: () => 0, load: k => { joined = c.get(k); return 'v'; } });
    const p = c.get('k'); assert.equal(await p, 'v'); assert.equal(await joined, 'v');
  }
  // Repeated invalidations and clear are separate barriers.
  {
    const gates = [deferred(), deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick(); c.clear();
    const d = c.get('k'); await tick(); assert.equal(calls, 3);
    gates[2].resolve(3); gates[1].resolve(2); gates[0].resolve(1);
    assert.deepEqual(await Promise.all([a, b, d]), [1, 2, 3]);
    assert.equal(await c.get('k'), 3);
  }
  console.log('all checks passed');
}
main().catch(e => { console.error(e); process.exit(1); });

