'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key).promise;
      // Only the flight still registered for key may unregister itself or
      // commit; a detached flight just settles its original callers.
      const flight = {};
      flight.promise = Promise.resolve().then(work).then(value => {
        if (pending.get(key) === flight) {
          pending.delete(key);
          commit(value);
        }
        return value;
      }, reason => {
        if (pending.get(key) === flight) pending.delete(key);
        throw reason;
      });
      pending.set(key, flight);
      return flight.promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

